function buildUrgentConfirmationEmail(opts) {
  const nowCST = new Date((/* @__PURE__ */ new Date()).toLocaleString("en-US", { timeZone: "America/Chicago" }));
  const todayStr = `${nowCST.getFullYear()}-${String(nowCST.getMonth() + 1).padStart(2, "0")}-${String(nowCST.getDate()).padStart(2, "0")}`;
  const tomorrowCST = new Date(nowCST);
  tomorrowCST.setDate(tomorrowCST.getDate() + 1);
  const tomorrowStr = `${tomorrowCST.getFullYear()}-${String(tomorrowCST.getMonth() + 1).padStart(2, "0")}-${String(tomorrowCST.getDate()).padStart(2, "0")}`;
  const apptDateRaw = opts.date.trim();
  const isTomorrow = apptDateRaw === tomorrowStr || apptDateRaw.startsWith(tomorrowStr);
  const isToday = apptDateRaw === todayStr || apptDateRaw.startsWith(todayStr);
  let hoursUntilAppt = null;
  if (isToday && opts.time) {
    try {
      const timeMatch = opts.time.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
      if (timeMatch) {
        let apptHour = parseInt(timeMatch[1], 10);
        const apptMin = parseInt(timeMatch[2], 10);
        const meridiem = (timeMatch[3] ?? "").toUpperCase();
        if (meridiem === "PM" && apptHour < 12) apptHour += 12;
        if (meridiem === "AM" && apptHour === 12) apptHour = 0;
        const apptMinutes = apptHour * 60 + apptMin;
        const nowMinutes = nowCST.getHours() * 60 + nowCST.getMinutes();
        const diffMins = apptMinutes - nowMinutes;
        if (diffMins > 0) hoursUntilAppt = Math.round(diffMins / 60);
      }
    } catch (_) {
    }
  }
  let whenLabel;
  let whenBody;
  let headerSubLabel;
  if (isToday && hoursUntilAppt !== null && hoursUntilAppt > 0) {
    const hrWord = hoursUntilAppt === 1 ? "1 hour" : `${hoursUntilAppt} hours`;
    whenLabel = `IN ${hrWord.toUpperCase()}`;
    whenBody = `in <strong>${hrWord}</strong>`;
    headerSubLabel = `Your appointment starts in ${hrWord} \u2014 please confirm using the link below`;
  } else if (isToday) {
    whenLabel = "TODAY";
    whenBody = "today";
    headerSubLabel = "Your appointment is today \u2014 please confirm using the link below";
  } else if (isTomorrow) {
    whenLabel = "TOMORROW";
    whenBody = "tomorrow";
    headerSubLabel = "Your appointment is tomorrow \u2014 please confirm using the link below";
  } else {
    whenLabel = "SOON";
    whenBody = "soon";
    headerSubLabel = "Your appointment is coming up \u2014 please confirm using the link below";
  }
  const subject = `\u26A0\uFE0F URGENT: Please Confirm Your Appointment ${whenLabel}`;
  const serviceDesc = [opts.vehicleType, opts.packageType].filter(Boolean).join(" \u2014 ");
  const citySlug = opts.city || opts.location || null;
  const cityLabel = citySlug ? citySlug.split(/[_\s]+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ") + ", FL" : null;
  const addressLine = opts.address ? [opts.address, cityLabel].filter(Boolean).join(", ") : cityLabel;
  const serviceRow = serviceDesc ? '<tr><td style="color:#64748b;font-size:13px;width:120px;padding-bottom:10px;">\u{1F697} Service</td><td style="color:#111827;font-size:14px;padding-bottom:10px;">' + serviceDesc + "</td></tr>" : "";
  const locationRow = addressLine ? '<tr><td style="color:#64748b;font-size:13px;">\u{1F4CD} Location</td><td style="color:#111827;font-size:14px;">' + addressLine + "</td></tr>" : "";
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"><tr><td align="center"><table width="100%" style="max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.10);"><tr><td style="background:linear-gradient(135deg,#dc2626 0%,#b91c1c 100%);padding:32px 28px;text-align:center;"><div style="font-size:48px;margin-bottom:12px;">\u26A0\uFE0F</div><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:800;">Action Required</h1><p style="margin:8px 0 0;color:rgba(255,255,255,0.85);font-size:14px;">` + headerSubLabel + '</p></td></tr><tr><td style="padding:28px;"><p style="margin:0 0 16px;color:#374151;font-size:16px;line-height:1.6;">Hi <strong>' + opts.firstName + `</strong>,</p><p style="margin:0 0 20px;color:#374151;font-size:15px;line-height:1.6;">We still haven't received your confirmation for your appointment ` + whenBody + '. Please confirm using the link below so we can keep your detailer on schedule.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#fef2f2;border-radius:12px;padding:20px;margin-bottom:24px;border:1px solid #fecaca;"><tr><td><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="color:#64748b;font-size:13px;width:120px;padding-bottom:10px;">\u{1F4C5} Date</td><td style="color:#111827;font-size:14px;font-weight:700;padding-bottom:10px;">' + opts.date + '</td></tr><tr><td style="color:#64748b;font-size:13px;padding-bottom:10px;">\u23F0 Time</td><td style="color:#111827;font-size:14px;font-weight:700;padding-bottom:10px;">' + opts.time + "</td></tr>" + serviceRow + locationRow + '</table></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"><tr><td align="center"><a href="' + opts.confirmUrl + '" style="display:inline-block;background:#dc2626;color:#ffffff;font-size:17px;font-weight:800;text-decoration:none;padding:16px 40px;border-radius:50px;letter-spacing:0.3px;box-shadow:0 4px 12px rgba(220,38,38,0.35);">\u2705 Confirm My Appointment Now</a></td></tr></table><p style="margin:0 0 8px;color:#6b7280;font-size:13px;text-align:center;">Button not working? <a href="' + opts.confirmUrl + '" style="color:#dc2626;">Click here to confirm</a></p><p style="margin:0 0 24px;color:#6b7280;font-size:13px;text-align:center;">Need to reschedule? Call or text us immediately at <strong>850-517-7874</strong></p><hr style="border:none;border-top:1px solid #e5e7eb;margin:0 0 16px;"><p style="margin:0;color:#9ca3af;font-size:12px;text-align:center;">Luxury Wash On Wheels \xB7 Automated Appointment Reminder<br>If you do not confirm, we may need to reassign your detailer.</p></td></tr></table></td></tr></table></body></html>';
  return { subject, html };
}
function buildOnTheWayEmail(opts) {
  const subject = `\u{1F697} Your detailer ${opts.detailerFirstName} is on the way!`;
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"><tr><td align="center"><table width="100%" style="max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.10);"><tr><td style="background:linear-gradient(135deg,#0057FF 0%,#0041CC 100%);padding:32px 28px;text-align:center;"><div style="font-size:48px;margin-bottom:12px;">\u{1F697}</div><h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:800;">Your Detailer Is On The Way!</h1><p style="margin:8px 0 0;color:rgba(255,255,255,0.85);font-size:14px;">Track their live location below</p></td></tr><tr><td style="padding:28px;"><p style="margin:0 0 16px;color:#374151;font-size:16px;line-height:1.6;">Hi <strong>` + opts.customerFirstName + '</strong>,</p><p style="margin:0 0 20px;color:#374151;font-size:15px;line-height:1.6;"><strong>' + opts.detailerFirstName + '</strong> is on their way to you right now. You can track their live location using the button below.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"><tr><td align="center"><a href="' + opts.trackUrl + '" style="display:inline-block;background:#0057FF;color:#ffffff;font-size:17px;font-weight:800;text-decoration:none;padding:16px 40px;border-radius:50px;letter-spacing:0.3px;box-shadow:0 4px 12px rgba(0,87,255,0.35);">\u{1F4CD} Track Live Location</a></td></tr></table><p style="margin:0 0 8px;color:#6b7280;font-size:13px;text-align:center;">Button not working? <a href="' + opts.trackUrl + `" style="color:#0057FF;">Click here to track</a></p><p style="margin:0 0 24px;color:#6b7280;font-size:13px;text-align:center;">Questions? Call or text us at <strong>850-517-7874</strong></p><hr style="border:none;border-top:1px solid #e5e7eb;margin:0 0 16px;"><p style="margin:0;color:#9ca3af;font-size:12px;text-align:center;">Luxury Wash On Wheels &middot; We'll see you soon!</p></td></tr></table></td></tr></table></body></html>`;
  return { subject, html };
}
