  // ─── Community Posts ──────────────────────────────────────────────────────────
  community: router({
    listPosts: publicProcedure.input(z3.object({ category: z3.string().optional(), limit: z3.number().optional() })).query(async ({ input }) => listCommunityPosts(input.category, input.limit ?? 50)),
    createPost: publicProcedure.input(z3.object({
      postId: z3.string(),
      authorId: z3.string(),
      authorName: z3.string(),
      title: z3.string(),
      body: z3.string(),
      category: z3.string().optional(),
      mediaUrls: z3.array(z3.string()).optional()
    })).mutation(async ({ input }) => {
      await createCommunityPost({ ...input, mediaUrls: input.mediaUrls ? JSON.stringify(input.mediaUrls) : null });
      try {
        const { employees: empTable } = await Promise.resolve().then(() => (init_schema(), schema_exports));
        const { ne: ne2 } = await import("drizzle-orm");
        const drizzleDb = await getDb();
        if (drizzleDb) {
          const recipients = await drizzleDb.select({ pushToken: empTable.pushToken }).from(empTable).where(ne2(empTable.employeeId, input.authorId));
          const tokens = recipients.map((r) => r.pushToken).filter((t2) => !!t2 && (t2.startsWith("ExponentPushToken[") || t2.startsWith("ExpoPushToken[")));
          if (tokens.length > 0) {
            const preview = input.body.slice(0, 80);
            const pushPayloads = tokens.map((to) => ({ to, title: `\u{1F4AC} ${input.authorName} posted in Community`, body: input.title || preview, sound: "default", data: { screen: "team-chat", channel: "community", tab: "community", senderId: input.authorId, senderName: input.authorName } }));
            await fetch("https://exp.host/--/api/v2/push/send", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(pushPayloads)
            });
          }
        }
      } catch (e) {
        console.error("[push] community post push failed:", e);
      }
      return { success: true };
    }),
    uploadMedia: publicProcedure.input(z3.object({
      base64: z3.string(),
      mimeType: z3.string(),
      fileName: z3.string().optional()
    })).mutation(async ({ input }) => {
      const suffix = Math.random().toString(36).substr(2, 8);
      const ext = input.mimeType.split("/")[1]?.split(";")[0] ?? "bin";
      const key = `community-media/${Date.now()}_${suffix}.${ext}`;
      const buffer = Buffer.from(input.base64, "base64");
      const { url } = await storagePut(key, buffer, input.mimeType);
      return { url };
    }),
    deletePost: publicProcedure.input(z3.object({ postId: z3.string() })).mutation(async ({ input }) => deleteCommunityPost(input.postId)),
    pinPost: publicProcedure.input(z3.object({ postId: z3.string(), isPinned: z3.boolean() })).mutation(async ({ input }) => pinCommunityPost(input.postId, input.isPinned)),
    likePost: publicProcedure.input(z3.object({ postId: z3.string(), employeeId: z3.string(), liked: z3.boolean() })).mutation(async ({ input }) => likeCommunityPost(input.postId, input.employeeId, input.liked)),
    getMyLikes: publicProcedure.input(z3.object({ employeeId: z3.string() })).query(async ({ input }) => getCommunityPostLikesByEmployee(input.employeeId)),
    listComments: publicProcedure.input(z3.object({ postId: z3.string() })).query(async ({ input }) => listCommunityComments(input.postId)),
    createComment: publicProcedure.input(z3.object({
      commentId: z3.string(),
      postId: z3.string(),
      authorId: z3.string(),
      authorName: z3.string(),
      body: z3.string()
    })).mutation(async ({ input }) => {
      await createCommunityComment(input);
      try {
        const { employees: empTable, communityPosts: communityPosts2, communityComments: communityComments2 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
        const { eq: eq9, inArray: inArray4 } = await import("drizzle-orm");
        const drizzleDb = await getDb();
        if (drizzleDb) {
          const posts = await drizzleDb.select({ authorId: communityPosts2.authorId, title: communityPosts2.title }).from(communityPosts2).where(eq9(communityPosts2.postId, input.postId)).limit(1);
          const postAuthorId = posts[0]?.authorId ?? null;
          const postTitle = posts[0]?.title ?? "a post";
          const priorComments = await drizzleDb.select({ authorId: communityComments2.authorId }).from(communityComments2).where(eq9(communityComments2.postId, input.postId));
          const priorCommenterIds = [...new Set(priorComments.map((c) => c.authorId))];
          const recipientIds = [...new Set([postAuthorId, ...priorCommenterIds].filter((id) => !!id && id !== input.authorId))];
          if (recipientIds.length > 0) {
            const recipients = await drizzleDb.select({ pushToken: empTable.pushToken, employeeId: empTable.employeeId }).from(empTable).where(inArray4(empTable.employeeId, recipientIds));
            const tokens = recipients.map((r) => r.pushToken).filter((t2) => !!t2 && (t2.startsWith("ExponentPushToken[") || t2.startsWith("ExpoPushToken[")));
            if (tokens.length > 0) {
              const preview = input.body.slice(0, 80);
              const pushPayloads = tokens.map((to) => ({ to, title: `\u{1F4AC} ${input.authorName} commented`, body: `On "${postTitle}": ${preview}`, sound: "default", data: { screen: "team-chat", channel: "community", tab: "community", postId: input.postId, senderId: input.authorId, senderName: input.authorName } }));
              await fetch("https://exp.host/--/api/v2/push/send", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(pushPayloads)
              });
            }
          }
        }
      } catch (e) {
        console.error("[push] community comment push failed:", e);
      }
      return { success: true };
    }),
    deleteComment: publicProcedure.input(z3.object({ commentId: z3.string(), postId: z3.string() })).mutation(async ({ input }) => deleteCommunityComment(input.commentId, input.postId))
  }),
