import { Router as Router2 } from "express";
import mysql4 from "mysql2/promise";
function getDb6() {
  return mysql4.createConnection(process.env.DATABASE_URL);
}
function normalizeNumber(num) {
  const digits = num.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  return `+${digits}`;
}
async function findLineByNumber(conn, twilioNumber) {
  const normalized = normalizeNumber(twilioNumber);
  const [rows] = await conn.execute(
    "SELECT * FROM phone_lines WHERE phone_number = ? AND is_active = 1 LIMIT 1",
    [normalized]
  );
  return rows[0] ?? null;
}
async function getActiveEmployees(conn) {
  const [rows] = await conn.execute(
    "SELECT employee_id, phone_number FROM employees WHERE active_status = 'active' AND role IN ('admin','office','operations_manager','sales') AND phone_number IS NOT NULL AND phone_number != ''"
  );
  return rows.map((r) => ({ employeeId: r.employee_id, phoneNumber: normalizeNumber(r.phone_number) })).filter((e) => Boolean(e.phoneNumber));
}
