init_email();
init_db();
import { Router as Router3 } from "express";
import mysql5 from "mysql2/promise";
import crypto3 from "crypto";
function getPublicUrl() {
  return process.env.PUBLIC_URL ?? "https://www.luxurywashonwheels.app";
}
async function getConnection2() {
  return mysql5.createConnection(process.env.DATABASE_URL);
}
function generateToken2() {
  return crypto3.randomBytes(32).toString("hex");
}
async function sendSms2(to, body) {
  if (process.env.SMS_ENABLED !== "true") {
    console.log("[SMS] Outbound SMS disabled \u2014 A2P campaign pending. Skipping to:", to);
    return;
  }
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  const fromNumber = process.env.TWILIO_PHONE_NUMBER;
  if (!accountSid || !authToken || !fromNumber) {
    console.warn("[Invoice] Twilio not configured \u2014 skipping SMS");
    return;
  }
  const toNumber = to.startsWith("+") ? to : `+1${to.replace(/\D/g, "")}`;
  const params = new URLSearchParams({ To: toNumber, From: fromNumber, Body: body });
  const response = await fetch(
    `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Authorization: `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`
      },
      body: params.toString()
    }
  );
  if (!response.ok) {
    const err = await response.text();
    console.error("[Invoice] Twilio SMS error:", err);
  }
}
